mapper.codeEditorJavascript:
// Deal Sheet Field Joins - Complete Code
// Input: Full GHL record from Module 11
// Output: All fields ready for Deal Sheet

const ghlRecord = input.ghlRecord || input.data || input;
const recordId = input.recordId || '';

// Ensure input is valid
if (!ghlRecord) {
  return { error: 'No GHL record provided' };
}

// Helper function to format currency
function formatCurrency(value) {
  if (!value || value === '' || value === null) return '';
  const num = parseFloat(value);
  if (isNaN(num)) return value;
  return '$' + num.toLocaleString('en-AU');
}

// Helper function to check if value exists
function hasValue(val) {
  return val !== null && val !== undefined && val !== '' && val !== '0';
}

// Format Type value (e.g., "02_eoi" -> "02 EOI")
function formatType(value) {
  if (!value) return '';
  let formatted = value.replace(/_/g, ' ');
  formatted = formatted.replace(/\b\w/g, l => l.toUpperCase());
  return formatted;
}

// Format Status value (e.g., "01_available" -> "01 Available")
function formatStatus(value) {
  if (!value) return '';
  let formatted = value.replace(/_/g, ' ');
  formatted = formatted.replace(/\b\w/g, l => l.toUpperCase());
  return formatted;
}

// Format Price Group value (e.g., "700_" -> "$700+", "500__700k" -> "$500-700k")
function formatPriceGroup(value) {
  if (!value) return '';
  let formatted = value.toString().trim();
  formatted = formatted.replace(/_+$/, '');

  if (formatted.includes('__')) {
    const parts = formatted.split('__');
    if (parts.length === 2) {
      const first = parts[0].replace(/[^0-9]/g, '');
      const second = parts[1].replace(/[^0-9]/g, '');
      if (first && second) {
        formatted = `$${first}-${second}k`;
      }
    }
  } else if (formatted.match(/^\d+$/)) {
    formatted = `$${formatted}+`;
  } else if (formatted.includes('$') || formatted.includes('Offers') || formatted.includes('Over')) {
    return formatted;
  } else if (formatted.match(/^\d+/)) {
    formatted = `$${formatted}`;
  }
  return formatted;
}

// Format Title Type value (e.g., "owners_corp_community" -> "Owners Corp/Community")
function formatTitleType(value) {
  if (!value) return '';
  if (value.toLowerCase().includes('not applicable')) {
    return 'N/A';
  }
  let formatted = value.replace(/_/g, ' ');
  formatted = formatted.replace(/\b\w/g, l => l.toUpperCase());
  formatted = formatted.replace(/Corp Community/gi, 'Corp/Community');
  return formatted;
}

// 1. Type - Format backend value to display
const type = formatType(ghlRecord.deal_type || '');

// 2. Packager - Direct mapping
const packager = ghlRecord.packager || '';

// 3. Sourcer - Direct mapping
const sourcer = ghlRecord.sourcer || '';

// 3.5. QA Approved - Direct mapping (blank or "Approved")
const qaApproved = ghlRecord.qa_approved || '';

// 4. Status - Format backend value to display (editable)
const status = formatStatus(ghlRecord.status || '');

// 5. Review Date - Date when approved (row created)
// Use Australia/Sydney timezone to ensure correct date (not UTC)
const now = new Date();
const reviewDate = new Intl.DateTimeFormat('en-AU', {
  timeZone: 'Australia/Sydney',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

// 6. Last Update - System date
// Use Australia/Sydney timezone to ensure correct date (not UTC)
const lastUpdate = new Intl.DateTimeFormat('en-AU', {
  timeZone: 'Australia/Sydney',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(now);

// 7. Property Address - Direct mapping
const propertyAddress = ghlRecord.property_address || '';

// Create portal link as HYPERLINK formula for Google Sheets
const WEBHOOK_URL = 'https://hook.eu1.make.com/g9pcjs2imabfea3viiy6213ejgrdprn1';
const API_URL = 'https://property-review-form.vercel.app';
const MODULE_1_WEBHOOK = 'https://hook.eu1.make.com/bkq23g13n4ae6spskdbwpru7hleol6sl';

let propertyAddressLink = propertyAddress;

if (recordId && propertyAddress) {
  const encodedAddress = encodeURIComponent(propertyAddress);
  const encodedWebhookUrl = encodeURIComponent(WEBHOOK_URL);
  const encodedModule1Webhook = encodeURIComponent(MODULE_1_WEBHOOK);
  const encodedApiUrl = encodeURIComponent(API_URL);

  const portalUrl = `https://property-packaging-form.vercel.app/portal?webhookUrl=${encodedWebhookUrl}&module1Webhook=${encodedModule1Webhook}&apiUrl=${encodedApiUrl}&recordId=${encodeURIComponent(recordId)}&propertyId=${encodeURIComponent(recordId)}&propertyAddress=${encodedAddress}`;

  const isQaApproved =
    (qaApproved || '').toString().trim().toLowerCase() === 'approved';

  if (isQaApproved) {
    propertyAddressLink = `=HYPERLINK("${portalUrl}", "${propertyAddress}")`;
  }
}

// 8. Asking - Join asking + asking_text (N/A for new properties if no asking)
let asking = ghlRecord.asking || '';
if (ghlRecord.asking_text && ghlRecord.asking_text.trim() !== '') {
  asking = `${asking} - ${ghlRecord.asking_text}`;
}
// For new properties, if no asking value, show N/A
const isNewProperty = ghlRecord.property_type && !ghlRecord.property_type.toLowerCase().includes('established');
if (isNewProperty && !asking) {
  asking = 'N/A';
}

// 9. Price Group - Format backend value to display
const priceGroup = formatPriceGroup(ghlRecord.price_group || '');

// 10. BA Message - Direct mapping
const baMessage = ghlRecord.message_for_ba || '';

// 11. Accept Acq' / Total $ - Different logic for Established vs New
let acceptAcqTotal = '';
const isEstablished = ghlRecord.property_type && ghlRecord.property_type.toLowerCase().includes('established');

if (isEstablished) {
  // Established: Show from - to range
  const from = ghlRecord.acceptable_acquisition__from;
  const to = ghlRecord.acceptable_acquisition__to;
  if (hasValue(from) && hasValue(to)) {
    acceptAcqTotal = `${formatCurrency(from)} – ${formatCurrency(to)}`;
  } else if (hasValue(from)) {
    acceptAcqTotal = formatCurrency(from);
  }
} else {
  // New properties: Check contract type
  const contractType = (ghlRecord.contract_type || '').toLowerCase();
  const isSplitContract = contractType.includes('split');

  const landPrice = ghlRecord.land_price;
  const buildPrice = ghlRecord.build_price;
  let totalPrice = ghlRecord.total_price;

  if (isSplitContract) {
    // Split Contract: Show Land, Build, Total
    if (hasValue(landPrice) && hasValue(buildPrice)) {
      // If total_price is empty or zero, calculate it by adding land + build
      if (!hasValue(totalPrice) || parseFloat(totalPrice) === 0) {
        const landNum = parseFloat(landPrice) || 0;
        const buildNum = parseFloat(buildPrice) || 0;
        totalPrice = (landNum + buildNum).toString();
      }
        acceptAcqTotal = `L = ${formatCurrency(landPrice)}\nB = ${formatCurrency(buildPrice)}\nT = ${formatCurrency(totalPrice)}`;
    }
  } else {
    // Single Contract: Show Total Price only
    if (hasValue(totalPrice)) {
      acceptAcqTotal = formatCurrency(totalPrice);
    }
  }
}

// 12. CONFIG - Bed/Bath/Garage combination
let config = '';
const isDual = ghlRecord.single_or_dual_occupancy && 
               ghlRecord.single_or_dual_occupancy.toLowerCase().includes('dual');
const bedsPrimary = (ghlRecord.beds_primary || '').toString().replace(/point/gi, '.');
const bedsSecondary = (ghlRecord.beds_additional__secondary__dual_key || '').toString().replace(/point/gi, '.');
const bathPrimary = (ghlRecord.bath_primary || '').toString().replace(/point/gi, '.');
const bathSecondary = (ghlRecord.baths_additional__secondary__dual_key || '').toString().replace(/point/gi, '.');
const garagePrimary = (ghlRecord.garage_primary || '').toString().replace(/point/gi, '.');
const garageSecondary = (ghlRecord.garage_additional__secondary__dual_key || '').toString().replace(/point/gi, '.');

if (isDual && hasValue(bedsSecondary)) {
  config = `${bedsPrimary || ''} + ${bedsSecondary || ''}\n${bathPrimary || ''} + ${bathSecondary || ''}\n${garagePrimary || ''} + ${garageSecondary || ''}`;
} else {
  config = `${bedsPrimary || ''}\n${bathPrimary || ''}\n${garagePrimary || ''}`;
}

// 13. Current Rent $ pw - Join primary + secondary (Established only)
let currentRent = '';
if (ghlRecord.property_type && ghlRecord.property_type.toLowerCase().includes('established')) {
  if (isDual && hasValue(ghlRecord.current_rent_secondary__per_week)) {
    const primary = parseFloat(ghlRecord.current_rent_primary__per_week || 0);
    const secondary = parseFloat(ghlRecord.current_rent_secondary__per_week || 0);
    const total = primary + secondary;
    currentRent = formatCurrency(total);
  } else if (hasValue(ghlRecord.current_rent_primary__per_week)) {
    currentRent = formatCurrency(ghlRecord.current_rent_primary__per_week);
  } else {
    currentRent = 'N/A';
  }
} else {
  currentRent = 'N/A';
}

// 14. Appraised Rent $ pw - Join primary + secondary ranges (All properties)
let appraisedRent = '';
const rentPrimaryFrom = parseFloat(ghlRecord.rent_appraisal_primary_from || 0);
const rentPrimaryTo = parseFloat(ghlRecord.rent_appraisal_primary_to || 0);
const rentSecondaryFrom = parseFloat(ghlRecord.rent_appraisal_secondary_from || 0);
const rentSecondaryTo = parseFloat(ghlRecord.rent_appraisal_secondary_to || 0);

if (isDual && hasValue(rentSecondaryFrom)) {
  const fromTotal = rentPrimaryFrom + rentSecondaryFrom;
  const toTotal = rentPrimaryTo + rentSecondaryTo;
  appraisedRent = `${formatCurrency(fromTotal)} - ${formatCurrency(toTotal)}`;
} else if (hasValue(rentPrimaryFrom) && hasValue(rentPrimaryTo)) {
  appraisedRent = `${formatCurrency(rentPrimaryFrom)} - ${formatCurrency(rentPrimaryTo)}`;
}

// 15. Land Size - Direct mapping
const landSize = ghlRecord.land_size || '';

// 16. Title Type - Format backend value to display
const titleType = formatTitleType(ghlRecord.title || '');

// 17. Year Built or Registration - Use year_built OR land_registration
let yearBuiltOrRegistration = '';
if (ghlRecord.property_type && ghlRecord.property_type.toLowerCase().includes('established')) {
  yearBuiltOrRegistration = ghlRecord.year_built || '';
} else {
  yearBuiltOrRegistration = ghlRecord.land_registration || '';
}

// 18. Selling Agent - Join name + email + mobile (3 lines)
let sellingAgent = '';
const agentName = ghlRecord.agent_name || '';
const agentEmail = ghlRecord.agent_email || '';
const agentMobile = ghlRecord.agent_mobile || '';

if (agentName || agentEmail || agentMobile) {
  sellingAgent = `${agentName}\n${agentEmail}\n${agentMobile}`;
}

// 19. Cashback or Rebat - Direct mapping
const cashbackType = ghlRecord.cashback_rebate_type || '';

// 20. Cashback or Rebate $ - Format as currency
const cashbackValue = hasValue(ghlRecord.cashback_rebate_value) ? formatCurrency(ghlRecord.cashback_rebate_value) : '';

// 21. Closing BA - Direct mapping (editable, may be empty initially)
const closingBA = ghlRecord.closing_ba || '';

// 22. Closing Price - Direct mapping (editable, may be empty initially)
const closingPrice = ghlRecord.closing_price || '';

// 23. Client_Closed - Direct mapping (editable, may be empty initially)
const clientClosed = ghlRecord.client_closed || '';

// 24. Closing_Date - Direct mapping (editable, may be empty initially)
const closingDate = ghlRecord.closing_date || '';

// 25. Sort_Key__Dont_edit - Type - Status - Price Group
const sortKey = `${type || ''} - ${status || ''} - ${priceGroup || ''}`;

// Debug: Log sortKey to verify it's calculated
console.log('sortKey calculated:', sortKey);

// Return all fields for Google Sheets
return {
  type,
  packager,
  sourcer,
  qaApproved,
  status,
  reviewDate,
  lastUpdate,
  propertyAddress: propertyAddressLink,
  asking,
  priceGroup,
  baMessage,
  acceptAcqTotal,
  config,
  currentRent,
  appraisedRent,
  landSize,
  titleType,
  yearBuiltOrRegistration,
  sellingAgent,
  cashbackType,
  cashbackValue,
  closingBA,
  closingPrice,
  clientClosed,
  closingDate,
  sortKey: sortKey,
  recordId
};

const pdfUrl = input.pdfUrl || '';
const qaApproved = input.qaApproved || '';
const displayText = qaApproved || '';

// Build HYPERLINK formula
// Format: =HYPERLINK("URL", "Display Text")
const hyperlinkFormula = pdfUrl 
  ? `=HYPERLINK("${pdfUrl}", "${displayText}")`
  : displayText; // Fallback to just text if no PDF URL

return {
  qaApprovedWithLink: hyperlinkFormula,
  pdfUrl: pdfUrl,
  qaApproved: qaApproved
};
